<h2>Calculate or validate barcode check digits</h2>
<p class="lead">Choose the barcode format and enter the numeric data digits or a complete barcode.</p>
<div class="form-grid"><div class="field"><label for="format">Barcode format</label><select id="format"><option value="EAN13" selected>EAN-13</option><option value="UPCA">UPC-A</option><option value="EAN8">EAN-8</option></select></div><div class="field full"><label for="digits">Digits</label><input id="digits" type="text" value="400638133393"><small>For calculation: EAN-13 uses 12 data digits, UPC-A 11, EAN-8 7. You may also enter the complete code to validate.</small></div></div>
<div class="tool-actions"><button class="btn btn-primary" id="calc">Check / Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Calculated check digit</span><strong id="check">—</strong></div><div class="metric"><span>Complete barcode</span><strong id="complete">—</strong></div><div class="metric"><span>Validation</span><strong id="valid">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div>
<script>
(()=>{
const $=id=>document.getElementById(id);
const num=id=>{const v=parseFloat($(id)?.value);return Number.isFinite(v)?v:0;};
const money=(v,c='')=>Number.isFinite(v)?c+v.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const dec=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const pct=v=>Number.isFinite(v)?v.toFixed(2)+'%':'—';
const note=(m,bad=false)=>{const el=$('note');if(el){el.textContent=m||'';el.className='helper'+(bad?' danger':'');}};
function checkDigit(data){let sum=0,rev=[...data].reverse();rev.forEach((ch,i)=>sum+=(+ch)*(i%2===0?3:1));return String((10-(sum%10))%10);}function go(){const fmt=$('format').value,s=$('digits').value.replace(/\s+/g,'');const lens={EAN13:[12,13],UPCA:[11,12],EAN8:[7,8]}[fmt];if(!/^\d+$/.test(s)||!lens.includes(s.length)){note(`Enter ${lens[0]} data digits to calculate or ${lens[1]} digits to validate ${fmt}.`,true);$('check').textContent=$('complete').textContent=$('valid').textContent='—';return;}if(s.length===lens[0]){const cd=checkDigit(s);$('check').textContent=cd;$('complete').textContent=s+cd;$('valid').textContent='Calculated';note('Check digit calculated using the standard alternating 3/1 weighting from the right.');}else{const data=s.slice(0,-1),cd=checkDigit(data),ok=cd===s.slice(-1);$('check').textContent=cd;$('complete').textContent=s;$('valid').textContent=ok?'Valid':'Invalid';note(ok?'The supplied check digit matches.':'The supplied check digit does not match the calculated value.',!ok);}}
if($('calc')) $('calc').addEventListener('click',go);
if($('reset')) $('reset').addEventListener('click',()=>{document.querySelectorAll('.tool-panel input,.tool-panel textarea,.tool-panel select').forEach(el=>{if(el.tagName==='SELECT') el.selectedIndex=0; else el.value=el.defaultValue;});go();});
document.querySelectorAll('.tool-panel input,.tool-panel select').forEach(el=>el.addEventListener('input',go));
go();
})();
</script>
